import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%83%91%E3%83%BC%E3%82%BD%E3%83%8A%E3%83%ABWiki%E3%81%AE%E7%94%BB%E5%83%8F%E7%AE%A1%E7%90%86.html","title":"パーソナルWikiの画像管理","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.28,"words":385},"filePathRelative":"パーソナルWikiの画像管理.md"}`),a={name:`パーソナルWikiの画像管理.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="パーソナルwikiの画像管理" tabindex="-1"><a class="header-anchor" href="#パーソナルwikiの画像管理"><span>パーソナルWikiの画像管理</span></a></h1><p>パーソナルWikiに画像を入れる事について。</p><h2 id="wikinameの移動が簡単に出来る必要がある" tabindex="-1"><a class="header-anchor" href="#wikinameの移動が簡単に出来る必要がある"><span>WikiNameの移動が簡単に出来る必要がある</span></a></h2><p>Wikiでは新しい記事に分離したりリネームしたり、 といった事が頻繁にやりやすいようにしておきたい。 だから画像を特定のWikiNameの添付のように扱うのは良くない。</p><p>ページの下半分を別のWikiNameに移動する、という時に、中に画像が入っているかなどは意識せずに移動出来る必要がある。</p><p>どこに移動していても、その画像を削除したり再編集したり、といった事が簡単に出来る必要がある。</p><h2 id="バルクに取り込める必要性" tabindex="-1"><a class="header-anchor" href="#バルクに取り込める必要性"><span>バルクに取り込める必要性</span></a></h2><p>画像を一つ一つ選んでペーストする、みたいな形式は、 10ページくらいの手書きノートを取り込む、みたいな時には不便だ。</p><p>画像とテキストをいったりきたりするのはストレスなので、 画像が多い時は画像をまとめて作って、一気にインポート出来る方が良い。</p><p><a href="./講義ノート.html">講義ノート</a>などのリアルタイム性高くとっていく必要がある時にもまとめて手書きでノートをとって、 あとからまとめてインポートする事になる。 だから画像はバルクで取り込む手段｢も｣ある方がいい。</p><h2 id="ファイラーやシェルスクリプトで簡単に扱える必要がある" tabindex="-1"><a class="header-anchor" href="#ファイラーやシェルスクリプトで簡単に扱える必要がある"><span>ファイラーやシェルスクリプトで簡単に扱える必要がある</span></a></h2><p>メモはアプリの寿命より長い。 だからアプリが無くなった後でも画像をある程度管理出来る必要がある。 だからフラットにidのファイルが延々と並ぶ、という形式は良く無い。</p><p>個人的にはフォルダ分けくらいが出来ればいいと思う。 フォルダ名でなんの画像なのかが分かり、 そのフォルダの中のpngファイルを見ていけばある程度は内容が分かるのが良い。 日付のフォルダとかは後で探す時に不便なので良くない。 やはり短いフォルダ名を自分でつけられる必要がある。</p><p>また画像回りの編集は環境や状況によって求められるものが多様なので、 Wikiアプリの中に組みこむには不足が多い。 だから外部のアプリとのやりとりを、アプリを介さずに出来る方が良い。 画像の編集は必要に応じて違うアプリやスクリプトを使える方が良い。</p><p>例えば<a href="./Wikiと手書きノートの融合.html">Wikiと手書きノートの融合</a>などでは画像の余白を除去するgoスクリプトを挟んだりしている。 こういう事が出来るように、画像はアプリが抱え持つのではなく、 プレーンなファイルとして管理出来る方が良い。</p><p>アプリの寿命だけに限らず、単にファイラーで管理出来るのは割と重要だ。 バックアップや移動、削除など、画像単体でのとりまわしの良さは、 思ったよりも利益が多い。 ファイラーで直接画像を順番に眺められる方が、Wiki越しよりも便利な事も多い。 <a href="./VuePress.html">VuePress</a>で公開しようとした時に画像が表示されない！とかのトラブルシュートも、 ファイラーで簡単に確認出来るように管理されてる方がずっと簡単だ。</p><p>結局、画像の管理はテキストとは独立｢にも｣行える方が良い。</p><h2 id="パーソナルwikiシステムは、画像の管理を決めすぎない方が良い" tabindex="-1"><a class="header-anchor" href="#パーソナルwikiシステムは、画像の管理を決めすぎない方が良い"><span>パーソナルWikiシステムは、画像の管理を決めすぎない方が良い</span></a></h2><p>画像の管理はテキストの管理とは違った要求があり、 使ってるデバイスやノートをとっているシチュエーションなど、 いろいろな事情で最適解が異る。 しかもこれらの事情は同じ人でも時期によって異ったりする。(学生と社会人になったあと、転職、など)</p><p>メモはそうした状況の変化よりも長生きするので、そうした状況の何かを決めうちしてしまうのではなく、 状況ごとにあわせた解決策を柔軟に選べる必要がある。</p><p>だからWikiアプリが何かのポリシーをあまり決めすぎない方が良い。 やはり画像も、アプリのものではなくてデータの方が主役であるべきだ。</p>`,21)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};